CREATE DATABASE IF NOT EXISTS supermercado_yahweh CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE supermercado_yahweh;
DROP TABLE IF EXISTS movimientos_inventario; DROP TABLE IF EXISTS productos; DROP TABLE IF EXISTS proveedores; DROP TABLE IF EXISTS categorias; DROP TABLE IF EXISTS usuarios;
CREATE TABLE usuarios(id_usuario INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL,usuario VARCHAR(50) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,rol ENUM('administrador','empleado') NOT NULL DEFAULT 'empleado',estado ENUM('activo','inactivo') NOT NULL DEFAULT 'activo',fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categorias(id_categoria INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,descripcion VARCHAR(255));
CREATE TABLE proveedores(id_proveedor INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,telefono VARCHAR(30),direccion VARCHAR(180));
CREATE TABLE productos(id_producto INT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(50) NOT NULL UNIQUE,nombre VARCHAR(150) NOT NULL,id_categoria INT NOT NULL,precio_compra DECIMAL(12,2) NOT NULL DEFAULT 0,precio_venta DECIMAL(12,2) NOT NULL DEFAULT 0,cantidad INT NOT NULL DEFAULT 0,stock_minimo INT NOT NULL DEFAULT 0,fecha_vencimiento DATE NULL,fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_producto_categoria FOREIGN KEY(id_categoria) REFERENCES categorias(id_categoria));
CREATE TABLE movimientos_inventario(id_movimiento INT AUTO_INCREMENT PRIMARY KEY,id_producto INT NOT NULL,id_usuario INT NOT NULL,tipo_movimiento ENUM('entrada','salida') NOT NULL,cantidad INT NOT NULL,fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,observacion VARCHAR(255),CONSTRAINT fk_mov_producto FOREIGN KEY(id_producto) REFERENCES productos(id_producto),CONSTRAINT fk_mov_usuario FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario));
